import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';

interface ICurrentTimeInTimezoneProps extends HTMLAttributes<HTMLPreElement> {
  timezone: string;
}

const CurrentTimeInTimezone: React.FC<ICurrentTimeInTimezoneProps> = ({ timezone, ...rest }) => {
  const timerRef = React.useRef<ReturnType<typeof setTimeout>>(undefined);
  const elRef = React.useRef<HTMLPreElement>(null);

  React.useEffect(() => {
    const update = () => {
      if (!elRef.current) return;
      elRef.current.textContent = new Date().toLocaleString(navigator.language, {
        timeZone: timezone,
        timeZoneName: 'short',
      });
    };
    timerRef.current = setInterval(update, 1000);
    update();
    return () => timerRef.current && clearInterval(timerRef.current);
  }, []);

  return <pre ref={elRef} {...rest} className={clsx('p-0 m-0', rest.className)} />;
};

export default CurrentTimeInTimezone;
