import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingTimezoneItem } from '../@mappers/hikingTimezones.mapper';
import {
  IHikingTimezoneCreateDTO,
  IHikingTimezoneDTO,
  IHikingTimezoneUpdateDTO,
} from '../@types/hiking.backendTypes';
import { IHikingTimezone } from '../@types/hiking.baseTypes';

export const getHikingTimezones = async (id_hiking: number): Promise<IHikingTimezone[]> => {
  const res = await get<IHikingTimezoneDTO[]>('/ajax/hiking/timezones/timezones.php', {
    id_hiking,
  });
  return res.map(mapHikingTimezoneItem);
};

export const addHikingTimezone = async (data: IHikingTimezoneCreateDTO): Promise<number> => {
  const res = await post<any, IHikingTimezoneCreateDTO>(
    '/ajax/hiking/timezones/timezone_add.php',
    data,
  ).then<{ id: string }>(handleApiError);
  return +res.id;
};

export const updateHikingTimezone = async (data: IHikingTimezoneUpdateDTO): Promise<boolean> => {
  const res = await post<any, IHikingTimezoneUpdateDTO>(
    '/ajax/hiking/timezones/timezone_edit.php',
    data,
  ).then<{ success: string }>(handleApiError);
  return Boolean(res?.success);
};

export const deleteHikingTimezone = async (id_hiking: number, id: number): Promise<boolean> => {
  const res = await post<any, { id: number; id_hiking: number }>(
    '/ajax/hiking/timezones/timezone_del.php',
    { id_hiking, id },
  ).then<{ success: string }>(handleApiError);
  return Boolean(res?.success);
};
